mi2_urls=[]
for d in MI2_COUNTIES:
    sections=[
        ('Michigan onsite-wastewater framework','Michigan EGLE states that onsite wastewater management is a required local-health-department service under the Michigan Public Health Code. Local health departments carry out ordinary onsite permitting and review while EGLE provides oversight, technical support, and review for certain larger or specialized systems.'),
        ('Confirm project scope before construction','Local sanitary codes, sewer availability, wastewater flow, commercial use, property additions, replacement work, and alternative or engineered systems can change the approval path. Use the current county instructions and any applicable EGLE review before excavation or installation.')
    ]+d['sections']
    sources=[('Michigan EGLE — Onsite Wastewater Management',MI2_EGLE),('Michigan EGLE — Onsite program contacts and direct-oversight counties',MI2_EGLE_CONTACT)]+d['sources']
    mi2_urls.append(write_county_page('Michigan','michigan',d['county'],d['authority'],d['contact'],sections,sources,verified='August 30, 2026'))

# Guard this validated batch before nationwide fallback generation. The nationwide layer detects existing pages as verified and must not replace them.
for d in MI2_COUNTIES:
    p=OUTPUT/'counties'/'michigan'/slugify(d['county'])/'index.html'
    t=p.read_text(encoding='utf-8')
    if 'Local septic rules not yet verified' in t or 'VERIFIED' not in t.upper() or 'Official sources' not in t:
        raise RuntimeError(f'Michigan additional verified page failed: {d["county"]}')

print(f'Michigan additional expansion complete: +{len(mi2_urls)} verified county guides; 8 verified Michigan counties total')

